// focus: single-text token counting
// source: bench/harness/src/corpus.rs:115-121
fn count_tokens(tokenizer: &Tokenizer, text: &str) -> Result<usize> {
    let enc = tokenizer
        .encode(text, false)
        .map_err(|e| anyhow::anyhow!("encode: {e}"))
        .context("tokenizer encode failed")?;
    Ok(enc.get_ids().len())
}

